import React, { useState, useEffect } from "react";
import axios from "axios";
import styled from "styled-components";

// Styled Components
const FuelPageWrapper = styled.div`
  font-family: Arial, sans-serif;
  max-width: 600px;
  margin: 20px auto;
  padding: 20px;
  border: 1px solid #ddd;
  border-radius: 8px;
`;

const Heading = styled.h1`
  text-align: center;
`;

const FormWrapper = styled.div`
  margin-bottom: 20px;
`;

const Label = styled.label`
  display: block;
  margin-top: 10px;
  font-weight: bold;
`;

const Input = styled.input`
  width: 100%;
  padding: 8px;
  margin-top: 5px;
  margin-bottom: 10px;
  border: 1px solid #ccc;
  border-radius: 4px;
`;

const Button = styled.button`
  background-color: #4caf50;
  color: white;
  padding: 10px 15px;
  border: none;
  border-radius: 4px;
  cursor: pointer;

  &:hover {
    background-color: #45a049;
  }
`;

const Message = styled.div`
  margin-top: 10px;
  padding: 10px;
  border-radius: 4px;
  background-color: #dff0d8;
  color: #3c763d;
`;

const Error = styled.div`
  margin-top: 10px;
  padding: 10px;
  border-radius: 4px;
  background-color: #f2dede;
  color: #a94442;
`;

const FuelEntries = styled.div`
  margin-top: 20px;
`;

const EntriesList = styled.ul`
  list-style-type: none;
  padding: 0;
`;

const EntryItem = styled.li`
  margin-bottom: 20px;
`;

const HorizontalLine = styled.hr`
  border: 1px solid #ddd;
`;

const FuelPage = () => {
  const [registrationNumber, setRegistrationNumber] = useState("");
  const [dateFilled, setDateFilled] = useState("");
  const [bunkName, setBunkName] = useState("");
  const [litresFilled, setLitresFilled] = useState("");
  const [pricePerLitre, setPricePerLitre] = useState("");
  const [amountPaid, setAmountPaid] = useState("");
  const [fuelEntries, setFuelEntries] = useState([]);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");

  // Handle form submission for adding fuel details
  const handleAddFuel = async (e) => {
    e.preventDefault();

    const fuelData = {
      registration_number: registrationNumber,
      date_filled: dateFilled,
      bunk_name: bunkName,
      litres_filled: litresFilled,
      price_per_litre: pricePerLitre,
      amount_paid: amountPaid,
    };

    try {
      const response = await axios.post("/api/fuel/add", fuelData);
      setMessage(response.data.message);
      setError("");
      fetchFuelEntries(); // Refresh fuel entries
    } catch (error) {
      setError(error.response?.data?.error || "An error occurred");
      setMessage("");
    }
  };

  // Fetch fuel entries for a specific registration number
  const fetchFuelEntries = async () => {
    if (!registrationNumber) return;

    try {
      const response = await axios.get(`/api/fuel/byRegistration/${registrationNumber}`);
      setFuelEntries(response.data);
      setError("");
    } catch (error) {
      setFuelEntries([]);
      setError(error.response?.data?.error || "An error occurred");
    }
  };

  // Fetch fuel entries whenever registration number changes
  useEffect(() => {
    if (registrationNumber) {
      fetchFuelEntries();
    }
  }, [registrationNumber]);

  return (
    <FuelPageWrapper>
      <Heading>Fuel Details</Heading>

      <FormWrapper>
        <h2>Add Fuel Entry</h2>
        <form onSubmit={handleAddFuel}>
          <div>
            <Label>Registration Number:</Label>
            <Input
              type="text"
              value={registrationNumber}
              onChange={(e) => setRegistrationNumber(e.target.value)}
              required
            />
          </div>
          <div>
            <Label>Date Filled:</Label>
            <Input
              type="date"
              value={dateFilled}
              onChange={(e) => setDateFilled(e.target.value)}
              required
            />
          </div>
          <div>
            <Label>Bunk Name:</Label>
            <Input
              type="text"
              value={bunkName}
              onChange={(e) => setBunkName(e.target.value)}
              required
            />
          </div>
          <div>
            <Label>Litres Filled:</Label>
            <Input
              type="number"
              value={litresFilled}
              onChange={(e) => setLitresFilled(e.target.value)}
              required
            />
          </div>
          <div>
            <Label>Price Per Litre:</Label>
            <Input
              type="number"
              value={pricePerLitre}
              onChange={(e) => setPricePerLitre(e.target.value)}
              required
            />
          </div>
          <div>
            <Label>Amount Paid:</Label>
            <Input
              type="number"
              value={amountPaid}
              onChange={(e) => setAmountPaid(e.target.value)}
              required
            />
          </div>
          <Button type="submit">Add Fuel Entry</Button>
        </form>
      </FormWrapper>

      {message && <Message>{message}</Message>}
      {error && <Error>{error}</Error>}

      <FuelEntries>
        <h2>Fuel Entries</h2>
        <EntriesList>
          {fuelEntries.length === 0 ? (
            <EntryItem>No fuel entries found for this registration number.</EntryItem>
          ) : (
            fuelEntries.map((entry) => (
              <EntryItem key={entry.id}>
                <p><strong>Date:</strong> {entry.date_filled}</p>
                <p><strong>Bunk:</strong> {entry.bunk_name}</p>
                <p><strong>Litres Filled:</strong> {entry.litres_filled}</p>
                <p><strong>Price per Litre:</strong> {entry.price_per_litre}</p>
                <p><strong>Total Amount:</strong> {entry.total_amount}</p>
                <p><strong>Amount Paid:</strong> {entry.amount_paid}</p>
                <p><strong>Remaining Amount:</strong> {entry.remaining_amount}</p>
                <HorizontalLine />
              </EntryItem>
            ))
          )}
        </EntriesList>
      </FuelEntries>
    </FuelPageWrapper>
  );
};

export default FuelPage;
